import { MeshBasicNodeMaterial } from 'three/webgpu';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry } = ctx.THREE;

  // Root container (adapter will apply position/rotation/scale)
  const root = new Group();

  // ---------- Plane ----------
  const aspect = 512 / 320; // image aspect ratio
  const planeGeometry = new PlaneGeometry(aspect, 1);
  const planeMaterial = new MeshBasicNodeMaterial({ color: 0xffffff, map: null });
  const planeMesh = new Mesh(planeGeometry, planeMaterial);
  root.add(planeMesh);

  // Load texture asynchronously (material will update when ready)
  let textureRef;
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      textureRef = tex;
      planeMaterial.map = tex;
      planeMaterial.needsUpdate = true;
    });
  }

  // ---------- Text ----------
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const defaultColor = (config.visualSpec?.colors?.paper) ?? '#e8ecf2';
  for (const item of items) {
    const content = item.text ?? item.content ?? '';
    const fontSize = item.typography?.fontSize ?? 96;
    const txtObj = ctx.fontAtlas.createText(content, {
      fontSize,
      color: defaultColor,
      align: 'center',
    });
    // Position text slightly above the plane
    txtObj.position.set(0, 0.6, 0.01);
    root.add(txtObj);
  }

  // ---------- Cinematic Primitives ----------
  const primitiveInstances = [];
  const primitives = config.cinematicPrimitives ?? [];
  for (const prim of primitives) {
    const fn = ctx.primitives?.[prim.name];
    if (typeof fn === 'function') {
      const inst = fn(root, prim.params);
      primitiveInstances.push(inst);
    }
  }

  // ---------- UserData ----------
  root.userData.handlers = {};

  root.userData.cleanup = () => {
    // Cleanup primitives
    for (const inst of primitiveInstances) {
      if (inst && typeof inst.cleanup === 'function') {
        inst.cleanup();
      }
    }
    // Dispose material & geometry
    if (planeMaterial) planeMaterial.dispose();
    if (planeGeometry) planeGeometry.dispose();
    // Dispose texture
    if (textureRef && typeof textureRef.dispose === 'function') {
      textureRef.dispose();
    }
    // Remove children (including text objects)
    root.traverse((obj) => {
      if (obj !== root && obj.parent) {
        obj.parent.remove(obj);
        if (obj.geometry && typeof obj.geometry.dispose === 'function') obj.geometry.dispose();
        if (obj.material && typeof obj.material.dispose === 'function') obj.material.dispose();
      }
    });
  };

  return root;
}
